def max_Product(arr):
    if len(arr) < 2:
        raise ValueError("Array must contain at least two elements.")

    max1 = max2 = float('-inf')
    min1 = min2 = float('inf')

    for num in arr:
        # Update max1 and max2
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        # Update min1 and min2
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # The maximum product can be either max1 * max2 or min1 * min2
    return max((max1, max2), (min1, min2), key=lambda x: x[0] * x[1])
