```python
def dealnnoy_num(n, m):
    # Base cases
    if n == 0 and m == 0:
        return 1
    if n == 0 or m == 0:
        return 1

    # Use dynamic programming to compute the Delannoy number
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(n + 1):
        for j in range(m + 1):
            if i == 0 and j == 0:
                continue
            dp[i][j] = dp[i - 1][j] + dp[i][j - 1] + dp[i - 1][j - 1]

    return dp[n][m]
```

